#include <cuda_runtime.h>

extern "C" __global__ void scrc_k0(float* p0, float* p1, int p2) {
    const int input_row = static_cast<int>(blockIdx.x);
    float* const input = p0;
    const long long input_base = static_cast<long long>(input_row) * 16;
    const int lane = static_cast<int>(threadIdx.x % 16);
    float* const input_address = input + input_base + lane;
    const float loaded = *input_address;
    const unsigned int participants = __activemask();
    float reduced = loaded;
    reduced += __shfl_xor_sync(participants, reduced, 1, 16);
    reduced += __shfl_xor_sync(participants, reduced, 2, 16);
    reduced += __shfl_xor_sync(participants, reduced, 4, 16);
    reduced += __shfl_xor_sync(participants, reduced, 8, 16);
    const int output_row = static_cast<int>(blockIdx.x);
    float* const output = p1;
    float* const output_address = output + output_row;
    *output_address = reduced;
}

extern "C" __global__ void scrc_k0(const float* p0, float* p1, int p2) {
    int v1_load = static_cast<int>(blockIdx.x);
    const float* t0 = p0;
    const float* a0_base = t0 + v1_load * 16;
    int v2 = static_cast<int>(threadIdx.x);
    long long v2_wide = static_cast<long long>(v2);
    const float* a0_lane = a0_base + v2_wide;
    float v0 = *a0_lane;
    unsigned int participants = __activemask();
    v0 += __shfl_xor_sync(participants, v0, 8, 16);
    v0 += __shfl_xor_sync(participants, v0, 4, 16);
    v0 += __shfl_xor_sync(participants, v0, 2, 16);
    v0 += __shfl_xor_sync(participants, v0, 1, 16);
    int v1_store = static_cast<int>(blockIdx.x);
    float* t1 = p1;
    float* a1_base = t1 + v1_store;
    *a1_base = v0;
}

extern "C" __global__ void scrc_k0(const float* p0, float* p1, int p2) {
    const int input_row = static_cast<int>(blockIdx.x);
    const float* input_base = p0 + static_cast<long long>(input_row) * 16LL;
    const int reduction_lane = static_cast<int>(threadIdx.x);
    const long long reduction_lane_wide = static_cast<long long>(reduction_lane);
    float reduced = input_base[reduction_lane_wide];
    const unsigned int participants = __activemask();
    reduced += __shfl_xor_sync(participants, reduced, 8, 16);
    reduced += __shfl_xor_sync(participants, reduced, 4, 16);
    reduced += __shfl_xor_sync(participants, reduced, 2, 16);
    reduced += __shfl_xor_sync(participants, reduced, 1, 16);
    __syncthreads();
    const int output_row = static_cast<int>(blockIdx.x);
    p1[output_row] = reduced;
}
